import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"财务流水与提现","description":"灵萌财务管理：余额流水、积分流水、资金交易、提现审核与对账排查入口。","frontmatter":{"title":"财务流水与提现","description":"灵萌财务管理：余额流水、积分流水、资金交易、提现审核与对账排查入口。"},"headers":[],"relativePath":"features/finance.md","filePath":"features/finance.md","lastUpdated":1785020677000}'),i={name:"features/finance.md"};function l(n,t,d,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="财务流水与提现" tabindex="-1">财务流水与提现 <a class="header-anchor" href="#财务流水与提现" aria-label="Permalink to &quot;财务流水与提现&quot;">​</a></h1><p>路径：<strong>财务管理</strong></p><p>查询用户余额/积分变动、平台资金交易，并处理提现申请。本文教运营日常怎么查账、怎么审提现。</p><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li><a href="/features/payment">支付</a> / 微信支付等已配置完成</li><li>提现自动打款需在 <strong>系统配置 → 微信支付</strong> 中配好转账场景与证书（见 <a href="/features/wechat-pay">微信支付完整手册</a>）</li><li>账号具备财务管理相关菜单权限</li></ul><hr><h2 id="菜单一览" tabindex="-1">菜单一览 <a class="header-anchor" href="#菜单一览" aria-label="Permalink to &quot;菜单一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>余额流水</strong></td><td>查某用户余额增减（充值、消费、奖励、退款等）</td></tr><tr><td><strong>积分流水</strong></td><td>查积分增减（任务、签到、兑换等）</td></tr><tr><td><strong>资金交易</strong></td><td>查支付单、渠道交易状态</td></tr><tr><td><strong>提现处理</strong></td><td>审核用户提现、查看打款结果</td></tr></tbody></table><p>进阶对账：<strong>系统监控 → 对账中心</strong>（支付回调异常、账实不符时使用）。</p><hr><h2 id="一、查流水-客诉首选" tabindex="-1">一、查流水（客诉首选） <a class="header-anchor" href="#一、查流水-客诉首选" aria-label="Permalink to &quot;一、查流水（客诉首选）&quot;">​</a></h2><h3 id="余额-积分" tabindex="-1">余额 / 积分 <a class="header-anchor" href="#余额-积分" aria-label="Permalink to &quot;余额 / 积分&quot;">​</a></h3><ol><li>打开 <strong>余额流水</strong> 或 <strong>积分流水</strong></li><li>用用户 UID、时间范围筛选</li><li>对照业务：推广奖励、订单退款、管理员调账等</li></ol><h3 id="资金交易" tabindex="-1">资金交易 <a class="header-anchor" href="#资金交易" aria-label="Permalink to &quot;资金交易&quot;">​</a></h3><ol><li>打开 <strong>资金交易</strong></li><li>按订单号 / 支付单号 / 时间查</li><li>状态异常时：看支付回调是否成功 → 再看对账中心</li></ol><hr><h2 id="二、提现处理" tabindex="-1">二、提现处理 <a class="header-anchor" href="#二、提现处理" aria-label="Permalink to &quot;二、提现处理&quot;">​</a></h2><p>路径：<strong>财务管理 → 提现处理</strong></p><h3 id="日常审核流程" tabindex="-1">日常审核流程 <a class="header-anchor" href="#日常审核流程" aria-label="Permalink to &quot;日常审核流程&quot;">​</a></h3><ol><li>列表筛选「待处理」</li><li>核对用户身份、金额、历史流水是否合理</li><li><strong>通过</strong> 或 <strong>拒绝</strong>（拒绝建议填写原因，便于客服回复）</li><li>若已开自动打款：通过后关注打款状态；失败则按微信支付/支付宝错误信息排查</li></ol><h3 id="自动打款未开通时" tabindex="-1">自动打款未开通时 <a class="header-anchor" href="#自动打款未开通时" aria-label="Permalink to &quot;自动打款未开通时&quot;">​</a></h3><p>通过后可能仍需人工打款（以页面状态为准）。请在系统配置中补齐转账能力后再开自动。</p><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>测试用户产生一笔余额变动（如领推广奖励），<strong>余额流水</strong> 可见</li><li>发起小额提现，<strong>提现处理</strong> 出现申请</li><li>审核通过后，用户余额扣减正确；自动打款时微信侧到账或日志成功</li><li>支付一笔测试订单，<strong>资金交易</strong> 状态成功</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>有支付成功但流水没有</td><td>查资金交易与对账中心；是否重复回调失败</td></tr><tr><td>提现一直失败</td><td>转账场景 ID、证书、商户权限；用户真实姓名与微信实名</td></tr><tr><td>积分有、余额没有</td><td>业务发的是积分不是余额；看推广/任务配置</td></tr><tr><td>菜单看不到</td><td><a href="/config/my-modules">我的模块</a> 与 <a href="/config/admin-permissions">账号权限</a></td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/payment">支付与提现</a></li><li><a href="/features/wechat-pay">微信支付（完整）</a></li><li><a href="/features/promotion">推广员体系</a></li><li><a href="/ops/monitoring">系统监控入口</a></li></ul>',32)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
